import json
from pathlib import Path

from .base_client import BaseClient, NoStoreForPostalCode

# postal code -> closest Super Fresh store, generated by scripts/build_super_fresh_stores.py
STORES_FILE = Path(__file__).resolve().parent.parent / "postal_code" / "super_fresh_stores.json"


class SuperFreshClient:

    # loaded once from STORES_FILE
    _stores_by_postal_code: dict | None = None
    _default_store: int = 2

    # https://msf-api.gta.com.gt/api/products/search
    base_url = "https://msf-api.gta.com.gt/api/products/search"

    body =  {
             "version": "5.1.6",
             "channel": "web",
             "search_term": "Monster",
             "qty": 0,
             "store": {"code": 2}
             }

    def search_products(self, product, postal_code=None):
        # copy so the class-level body is never mutated between requests
        body = {**self.body, "search_term": product, "store": {"code": self.get_store(postal_code)}}

        base_client = BaseClient()

        response = base_client.post(
            self.base_url,
            json=body,
            headers={
                'Accept': "*/*",
                'Accept-Encoding': "gzip, deflate, br, zstd",
                'Accept-Language': "en-US,en;q=0.9",
                'Connection': "keep-alive",
                'Content-Type': "application/json",
                'Origin': "https://www.misuperfresh.com.gt",
                'Referer': "https://www.misuperfresh.com.gt/",
                'Sec-Fetch-Dest': "empty",
                'Sec-Fetch-Mode': "cors",
                'Sec-Fetch-Site': "cross-site",
                'TE': "trailers",
                'User-Agent': "Mozilla/5.0 (X11; Linux x86_64; rv:154.0) Gecko/20100101 Firefox/154.0"
            },
        )

        return response.json()

    def get_store(self, postal_code=None) -> int:
        # Super Fresh has no postal code -> store endpoint like the VTEX stores,
        # the store comes from the table made with the closest store to each zone
        cls = type(self)
        if cls._stores_by_postal_code is None:
            try:
                data = json.loads(STORES_FILE.read_text(encoding="utf-8"))
            except FileNotFoundError:
                # table not generated yet: every search uses the default store
                data = {}
            cls._stores_by_postal_code = data.get("postal_codes", {})
            cls._default_store = data.get("default_store", cls._default_store)

        if not postal_code or not cls._stores_by_postal_code:
            return cls._default_store

        store = (cls._stores_by_postal_code.get(postal_code) or {}).get("store")
        if store is None:
            # no Super Fresh store inside its coverage radius for that zone
            raise NoStoreForPostalCode(postal_code)
        return store
